 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the full uniform separator with the rarest color in the grid.
    lines = []
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            lines.append(('col', c, grid[0][c]))
    for r in range(h):
        if all(x == grid[r][0] for x in grid[r]):
            lines.append(('row', r, grid[r][0]))
    kind, idx, sep_color = min(lines, key=lambda q: sum(row.count(q[2]) for row in grid))
    if kind == 'col':
        a = [row[:idx] for row in grid]
        b = [row[idx + 1:] for row in grid]
    else:
        a, b = grid[:idx], grid[idx + 1:]
    rows = min(len(a), len(b))
    cols = min(len(a[0]), len(b[0]))
    # Align panels adjacent to the divider if sizes differ.
    if kind == 'row':
        a, b = a[-rows:], b[:rows]
    else:
        a = [row[-cols:] for row in a]
        b = [row[:cols] for row in b]
    ca = set(x for row in a for x in row)
    cb = set(x for row in b for x in row)
    common = ca & cb
    common.discard(sep_color)
    color = next(iter(common))
    return [[3 if a[r][c] == color and b[r][c] == color else color
             for c in range(cols)] for r in range(rows)]
